//! Actual Visual paths; listing/bid books retain their original private scope.
use super::*;
use super::state_columns::OriginalStateColumnsDataV1;
use oasis7_world_state::{incremental_owner_closure::CurrentMarketplaceProjectionDeltaV1,incremental_module_marketplace::ModuleMarketplaceFieldV1 as Kind};
use oasis7_world_state::observation_projection::current_commitment::{ProjectionColumnDataV1,ProjectionDataPathRefV1 as Path};
use oasis7_formal_protocol::{incremental_execution::{ExecutionTransaction,ExecutionFence},incremental_state::MerkleNodeReader};
use std::cell::RefCell;
fn id<'a>(semantic:&'a[u8],common:&mut FormalBoundedContextV1<'_>)->Result<&'a str,BodyMutationError>{common.charge(1,semantic.len()as u64).map_err(paid)?;match oasis7_world_state::incremental_semantic_key::read_semantic_key_v1(semantic).map_err(invalid)?{oasis7_world_state::incremental_semantic_key::SemanticKeyRefV1::Text(id)=>Ok(id),_=>Err(invalid("actual visual entity key"))}}
pub(super) fn fold_market_observation_v1<M:MerkleNodeReader>(before:&ProjectionColumnDataV1,state:&OriginalStateColumnsDataV1,source:&CurrentMarketplaceProjectionDeltaV1,tx:&ExecutionTransaction<'_,M>,max_json:usize,common:&mut FormalBoundedContextV1<'_>,live:&ExecutionFence)->Result<ProjectionColumnDataV1,BodyMutationError>{source.validate(tx,common.memory(),live)?;let memory=common.memory().clone();let mut out=before.share_data(&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;let shared=RefCell::new(common);let field=Kind::VisualEntities.name();
 source.visit_entities_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,_key,before,after,_meta|{if kind!=Kind::VisualEntities{return Ok(())}let mut common=shared.borrow_mut();let id=id(semantic,&mut common)?;let old=out.object_member_data(field,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;let present=match old{Some(old)=>old.object_member_data(id,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?.is_some(),None=>false};if present!=before{return Err(invalid("actual visual before presence"))}
 if !after{out=out.with_path_data_v1(&[Path::Field(field),Path::Field(id)],None,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;}else if !before{let rows=state.map_data_v1(field,&mut common)?.ok_or_else(||invalid("actual visual raw map missing"))?;let record=rows.row_data_v1(semantic,&mut common)?.and_then(|r|r.market_record_v1()).ok_or_else(||invalid("actual visual raw record missing"))?;let meter=RefCell::new(&mut**common);let first=RefCell::new(None);let view=record.serialization_v1(&meter,&first);let bytes=super::shared_json::capture_shared_v1(&view,&meter,&first,max_json)?;let common=meter.into_inner();let value=super::observation::data(&bytes,common)?;out=super::observation::ensure_field(&out,field,common)?;out=out.with_path_data_v1(&[Path::Field(field),Path::Field(id)],Some(&value),&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;}Ok::<_,BodyMutationError>(())})?;
 // A changed anchor discriminant installs exactly its actual new typed branch
 // before field-level edits; no missing intermediate object is fabricated.
 source.visit_existing_visual_patches_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|semantic,_key,name,_value|{if name!="anchor_kind"{return Ok(())}let mut common=shared.borrow_mut();let id=id(semantic,&mut common)?;let rows=state.map_data_v1(field,&mut common)?.ok_or_else(||invalid("actual visual raw map missing"))?;let record=rows.row_data_v1(semantic,&mut common)?.and_then(|r|r.market_record_v1()).ok_or_else(||invalid("actual visual raw record missing"))?;let bytes=record.actual_anchor_json_v1(&mut common)?;let value=super::observation::data(&bytes,&mut common)?;out=out.with_path_data_v1(&[Path::Field(field),Path::Field(id),Path::Field("anchor")],Some(&value),&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;Ok::<_,BodyMutationError>(())})?;
 source.visit_existing_visual_patches_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|semantic,_key,name,value|{let mut common=shared.borrow_mut();let id=id(semantic,&mut common)?;let mut path=[Path::Field(field),Path::Field(id),Path::Field(name),Path::Field(""),Path::Field(""),Path::Field("")];let mut replacement=None;let length=match name{
 "entity_id"|"module_id"|"kind"=>3,
 "label_present"=>{if value!=Some(b"false".as_slice()){return Ok(())}path[2]=Path::Field("label");replacement=Some(b"null".as_slice());3},
 "label_text"=>{if value.is_none(){return Ok(())}path[2]=Path::Field("label");3},
 "anchor_kind"=>return Ok(()),
 "anchor_agent_id"|"anchor_location_id"=>{if value.is_none(){return Ok(())}path[2]=Path::Field("anchor");path[3]=Path::Field("data");path[4]=Path::Field(if name=="anchor_agent_id"{"agent_id"}else{"location_id"});5},
 "anchor_x_cm"|"anchor_y_cm"|"anchor_z_cm"=>{if value.is_none(){return Ok(())}path[2]=Path::Field("anchor");path[3]=Path::Field("data");path[4]=Path::Field("pos");path[5]=Path::Field(match name{"anchor_x_cm"=>"x_cm","anchor_y_cm"=>"y_cm",_=>"z_cm"});6},
 _=>return Err(invalid("actual visual scalar path"))};
 let input=replacement.or(value).ok_or_else(||invalid("actual visual required field removed"))?;let value=super::observation::data(input,&mut common)?;out=out.with_path_data_v1(&path[..length],Some(&value),&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;Ok::<_,BodyMutationError>(())})?;
 let common=shared.into_inner();if !state.original_field_emitted_v1(field,common)?{out=out.with_object_member_data(field,None,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;}source.validate(tx,common.memory(),live)?;Ok(out)
}
